	struct filename *tmp;
	struct file *spp_file = NULL;

	if (fd)
		return fd;

	tmp = getname(filename);
	if (IS_ERR(tmp))
		return PTR_ERR(tmp);

	spp_diag_trace_adapter_file_open_attempt(dfd, tmp->name, how->flags);

	fd = get_unused_fd_flags(how->flags);
	if (fd >= 0) {
		struct file *f = do_filp_open(dfd, tmp, &op);
		if (IS_ERR(f)) {
			put_unused_fd(fd);
			fd = PTR_ERR(f);
		} else {
			spp_file = f;
		}
	}
	putname(tmp);
	spp_diag_trace_adapter_file_open_return(fd, spp_file);
	if (spp_file)
		fd_install(fd, spp_file);
	return fd;
}

